Item.method_code:
const { item, itemNode, itemTypeName} = options;
if (!item && !itemNode) {
	return false;
}

const action = ArasModules.item.getAction(itemTypeName, item?.id)
const itemAction = item ? action : itemNode.getAttribute('action');
const discoverOnly = item ? item['@aras.discover_only'] : itemNode.getAttribute('discover_only');
const lockedById = item ? item['locked_by_id'] : aras.getItemProperty(itemNode, 'locked_by_id');
const id = item ? item.id : itemNode.getAttribute('id');
const isFixForApplications = ['mpp_ProcessPlan', 'mpp_Operation', 'mpp_Tool', 'Manufacturer Part'].includes(itemTypeName);
const isNew = isFixForApplications ? itemAction === 'add' : ArasModules.item.isNew(itemTypeName, id);
const canGet = discoverOnly !== '1';
const userId = aras.user.id;
const lockedByMe = lockedById === userId;
const isEdit = isNew || lockedByMe || itemAction === 'edit';

return isEdit && canGet;
